/** Unified registry — order = category order. */
export const RARE_TOOLS = [
  ...MAPS_TOOLS,
  ...SECURITY_TOOLS,
  ...GEMS_TOOLS,
  ...CLASSICS_TOOLS
];

export const getRareTool = (slug) => RARE_TOOLS.find(t => t.slug === slug);
export const getRareCat = (id) => RARE_CATS.find(c => c.id === id);
export const rareByCat = (catId) => RARE_TOOLS.filter(t => t.cat === catId);
